              "value": "전력·데이터센터: 17일 비츠로테크 상한가는 제너락의 Amazon 데이터센터 발전기 계약과 30년 이상 ATS 공급 이력의 연결로 설명됐다. 18일에는 선도전기 +30.0%, 가온전선 +26.1%, LS에코에너지 +14.0%, 대한전선 +12.0% 등 전선·전력기기가 상승했다. 전력망 접속 지연과 자가발전 수요가 주문의 배경이지만, 고객 계약 규모·납기·마진은 기업별로 따로 확인해야 한다. Google·Nvidia 등의 에너지 관리 동맹은 부하 이동·저장·자가발전으로 계통비용을 줄이려는 시도여서 전력 수요가 곧바로 모든 발전설비 주문으로 바뀌지는 않는다."
