          "title": "주간 판단 복기",
          "summary": "월러 발언 뒤 인상 기대와 금리·달러가 낮아졌고, 고용 발표 뒤에는 같은 변수들이 반대로 움직였다. 이 순서는 조건부 동결 발언이 주중 금리 하락의 중요한 촉매였다는 해석에 힘을 싣는다. 다만 당시 노동비용 지표와 포지션 조정도 함께 작용했을 가능성이 있어, 핵심은 특정 발언 하나보다 새 지표가 연준의 반응함수를 어떻게 바꾸었는지에 있다.",
